mapper.select:
SELECT id, user_id, pet_id, mode, last_message_at, created_at, updated_at
FROM ai_chat_sessions
WHERE user_id = #{userId}
  AND pet_id = #{petId}
  AND mode = #{mode}
LIMIT 1

SELECT id, user_id, pet_id, mode, last_message_at, created_at, updated_at
FROM ai_chat_sessions
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
